9	// BroadcastChannel lets tabs share freshly-refreshed tokens so that only one
10	// tab needs to hit the refresh endpoint. When another tab successfully refreshes
11	// we adopt the new token immediately, avoiding a redundant (and potentially
12	// conflicting) refresh request of our own.
13	const TOKEN_CHANNEL_NAME = "memos_token_sync";
14	
15	// Token refresh policy:
16	// - REQUEST_TOKEN_EXPIRY_BUFFER_MS: used for normal API requests.
17	// - FOCUS_TOKEN_EXPIRY_BUFFER_MS: used on tab visibility restore to refresh earlier.
18	export const REQUEST_TOKEN_EXPIRY_BUFFER_MS = 30 * 1000;
19	export const FOCUS_TOKEN_EXPIRY_BUFFER_MS = 2 * 60 * 1000;
20	
21	interface TokenBroadcastMessage {
22	  token: string;
23	  expiresAt: string; // ISO string
24	}
